(25, '2026-06-03 23:45:29', 'Tugas-pagi', 'Cek storage all server ', 'script ubah data di excel', '<div><span style=\"font-size: 15.2px;\">Sub FINAL_Storage_Report()</span></div><div><span style=\"font-size: 15.2px;\"><br></span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; Dim ws As Worksheet</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; Dim lastRow As Long</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; Dim i As Long</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; Dim dict As Object</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; Dim host As String</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; Dim keepMounts As Variant</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; Dim rng As Range</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; Dim serverName As String</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; Dim idx As Long</span></div><div><span style=\"font-size: 15.2px;\"><br></span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; Set ws = ThisWorkbook.Sheets(\"Storage Report\")</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; Set dict = CreateObject(\"Scripting.Dictionary\")</span></div><div><span style=\"font-size: 15.2px;\"><br></span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; \' ================= DAFTAR SERVER =================</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; \' Urutan baris di bawah ini otomatis menentukan urutan sorting di Excel</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; idx = 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"CCCM-fif-c0\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"DATA-ENTRY\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"Training_CC\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"ASSET-LOB-CC\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"TELEINTERVIEWER\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"SME-CentOs\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"FIF-MMU\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"fif-telesales-autodial\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"Sehati DC\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"RESERVE PROXY LB\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"APP_MTF_CS\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"mtf-cs-onebox-ubuntu\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"FIFWA_OFFICIAL\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"Grafana\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"WA-MUF\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"CCCM-reminder-autodial-app2\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"FIF_DC\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"Remedial\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"STORAGE 70.23\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"NAS 30.4\", idx: idx = idx + 1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; dict.Add \"LKS\", idx: